import countriesJson from '../data/countries.json'
import nameAlternativesJson from '../data/countryNameAlternatives.json'
import territorySubtitlesJson from '../data/territorySubtitles.json'
import type { CountryShape } from './countries'

// Facts about one country, generated by scripts/make-country-data.mjs.
export type CountryFacts = {
  // ISO 3166-1 alpha-3 code, e.g. "PER". Links facts to the globe outlines.
  isoAlpha3: string
  commonName: string
  officialName: string
  // Most countries have one capital; a few have several (e.g. South Africa).
  capitals: string[]
  // Total area including inland water, in square kilometres.
  areaKm2: number
  population: number
  populationYear: number
  // Human Development Index (0–1), before adjusting for inequality. Null when
  // UNDP has no value for the country. Not yet shown anywhere in the app.
  hdi: number | null
  hdiYear: number | null
  // Inequality-adjusted Human Development Index (0–1). Null when UNDP has no
  // value for the country, shown as "no data".
  ihdi: number | null
  ihdiYear: number | null
  // Our own estimate of the IHDI, worked out from the HDI, for countries that
  // have an HDI but no IHDI (null otherwise). Always shown as "estimated".
  ihdiEstimate: number | null
}

// All 195 countries (193 UN members + Vatican City and Palestine), keyed by
// ISO alpha-3 code.
export const countryFacts: Record<string, CountryFacts> = countriesJson

// The name to show for a country outline on the globe: our common name for the
// 195 countries, otherwise the map data's name (e.g. Greenland, Kosovo).
export function countryDisplayName(shape: Pick<CountryShape, 'name' | 'isoAlpha3'>): string {
  const facts = shape.isoAlpha3 === null ? undefined : countryFacts[shape.isoAlpha3]
  return facts?.commonName ?? shape.name
}

// Other names people often use for a country, e.g. "Turkey" for Türkiye,
// hand-written in countryNameAlternatives.json and keyed by ISO alpha-3 code.
// Most countries have none.
const nameAlternatives: Record<string, string[]> = nameAlternativesJson

export function alternativeNames(isoAlpha3: string): string[] {
  return nameAlternatives[isoAlpha3] ?? []
}

// What each map area outside the 195 countries is, e.g. "Autonomous
// territory of {DNK}" for Greenland, hand-written in territorySubtitles.json.
// Keyed by ISO alpha-3 code, or by the map data's name for areas with no code
// (Kosovo, etc.). A country's ISO code in braces stands for its common name,
// shown as a link to that country.
const territorySubtitles: Record<string, string> = territorySubtitlesJson

// One piece of a subtitle: plain text, or a country named by its ISO code.
export type SubtitlePart = { text: string } | { isoAlpha3: string; name: string }

// Splits a territory's subtitle into text and the countries it names, e.g.
// [{ text: 'Autonomous territory of ' }, { isoAlpha3: 'DNK', name: 'Denmark' }].
// Returns undefined for the 195 countries and areas with no subtitle.
export function territorySubtitle(
  shape: Pick<CountryShape, 'name' | 'isoAlpha3'>,
): SubtitlePart[] | undefined {
  const subtitle = territorySubtitles[shape.isoAlpha3 ?? shape.name]
  if (subtitle === undefined) return undefined
  // Splitting on a pattern with a capture group keeps the captured codes, so
  // the pieces alternate: text, code, text, code, ..., text.
  const pieces = subtitle.split(/\{([A-Z]{3})\}/)
  const parts: SubtitlePart[] = []
  pieces.forEach((piece, i) => {
    if (i % 2 === 1) parts.push({ isoAlpha3: piece, name: countryFacts[piece].commonName })
    else if (piece !== '') parts.push({ text: piece })
  })
  return parts
}
